/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { Observable, map } from 'rxjs';
import { LongTask } from 'app/shared/data/long-task.model';
import { LongTaskViewComponent } from './long-task-view.component';

/**
 * Muestra el progreso de una tarea larga en un diálogo.
 *
 * @example
 * this.longTask.run(title, this.repository.deleteSelection(filter)).subscribe(() => this.refresh());
 */
@Injectable({ providedIn: 'root' })
export class LongTaskService {
  private readonly dialog = inject(MatDialog);

  /** Emite y completa cuando el usuario cierra el diálogo. */
  run(title: string, progress: Observable<LongTask>): Observable<void> {
    return this.dialog
      .open(LongTaskViewComponent, { data: { title, progress } })
      .afterClosed()
      .pipe(map(() => undefined));
  }
}
